UPDATE outfit_logs SET selected_bottom = array_replace(selected_bottom, '바라클라바 (방한모)', '방풍 마스크/바라클라바') WHERE '바라클라바 (방한모)' = ANY(selected_bottom);
UPDATE outfit_logs SET selected_items = array_replace(selected_items, '바라클라바 (방한모)', '방풍 마스크/바라클라바') WHERE '바라클라바 (방한모)' = ANY(selected_items);
UPDATE outfit_logs SET selected_outer = '방풍 마스크/바라클라바' WHERE selected_outer = '방풍 글러브';
UPDATE outfit_logs SET selected_top = array_replace(selected_top, '방풍 글러브', '방풍 마스크/바라클라바') WHERE '방풍 글러브' = ANY(selected_top);
UPDATE outfit_logs SET selected_bottom = array_replace(selected_bottom, '방풍 글러브', '방풍 마스크/바라클라바') WHERE '방풍 글러브' = ANY(selected_bottom);
UPDATE outfit_logs SET selected_items = array_replace(selected_items, '방풍 글러브', '방풍 마스크/바라클라바') WHERE '방풍 글러브' = ANY(selected_items);
COMMIT;
